            if (entry.getValue() == 0) {
                queue.add(entry.getKey());
            }
        }
        int processed = 0;
        while (!queue.isEmpty()) {
            long current = queue.poll();
            processed++;
            for (Long next : adjacency.getOrDefault(current, List.of())) {
                int remaining = indegree.merge(next, -1, Integer::sum);
                if (remaining == 0) {
                    queue.add(next);
                }
            }
        }
        return processed < indegree.size();
    }
}

