        approve("GP-AE", "bob");
        approve("GP-AE", "carol");
        // 其他途径（任务创建）先加入同一条边：版本推进会先触发 409；
        // 这里直接验证版本匹配下重复边的整案拒绝：通过另一提案先行激活同样内容不可行，
        // 故构造任务创建后版本不匹配场景，断言整案 409 且图只含一条边
        incidentService.createTask("INC-A", "alice",
                new TaskCreateRequest(key(), "T-1", "G", "t", List.of("INC-B")));
        assertApiStatus(() -> graphService.activate("GP-AE", "alice",
                new GraphActivateRequest(key())), HttpStatus.CONFLICT);
        assertThat(graphService.getGraph().edges()).hasSize(1);
