                createReq(key(), "GP-RX", "carol", remove("INC-A", "INC-B")));
        approve("GP-RX", "alice");
        approve("GP-RX", "bob");
        approve("GP-RX", "carol");
        // 要删除的边不在当前图中 → 409
        assertApiStatus(() -> graphService.activate("GP-RX", "alice",
                new GraphActivateRequest(key())), HttpStatus.CONFLICT);
    }

    @Test
    void activate_addExistingEdge_conflict() {
        commanding("INC-A", "alice");
        commanding("INC-B", "bob");
        graphService.createProposal("pm", createReq(key(), "GP-AE", "carol", add("INC-A", "INC-B")));
